text(await tools.exec_command({cmd:"PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
import ast,csv,hashlib,json,re
from pathlib import Path
from jsonschema import Draft202012Validator
root=Path.cwd()
files=[*Path('regulatory-change-impact-brief').rglob('*'),*Path('tests').rglob('*'),Path('docs/verification/u02.md'),Path('docs/verification/u02-requirement-evidence.csv')]
files=[p for p in files if p.is_file()]
for p in files:
 data=p.read_text(encoding='utf-8')
 assert all(line==line.rstrip() for line in data.splitlines()),p
 if p.suffix=='.py':ast.parse(data,filename=str(p))
 if p.suffix=='.json':json.loads(data)
 if p.suffix=='.md':
  for target in re.findall(r'\[[^\]]+\]\(([^)]+)\)',data):
   if not target.startswith(('http:','https:','#')):
    assert (p.parent/target.split('#')[0]).exists(),(p,target)
schema_path=Path('regulatory-change-impact-brief/references/schemas/contracts.schema.json')
Draft202012Validator.check_schema(json.loads(schema_path.read_text()))
public=hashlib.sha256(Path('snapshot.schema.json').read_bytes()).hexdigest()
assert public=='8de9874ded18fa97294e83012796e4c386aa60ccfd30f8eca89cabdf2a267ac3'
assert hashlib.sha256(schema_path.read_bytes()).hexdigest() in Path('docs/verification/u02.md').read_text()
with Path('docs/verification/u02-requirement-evidence.csv').open(newline='') as f:rows=list(csv.DictReader(f))
assert len(rows)==49
assert sum(r['status']=='scoped-contract-demonstrated' for r in rows)==46
assert {r['requirement_id'] for r in rows if r['status']=='deferred'}=={'R3-023','R3-024','R3-025'}
