tools.exec_command({cmd:"sed -n '345,605p' regulatory-change-impact-brief/scripts/rci/snapshots.py",max_output_tokens:8500}),
tools.exec_command({cmd:"rg -n 'U02|freeze|R1|R3|R6|R10' TECHNICAL-DESIGN-AND-IMPLEMENTATION-PLAN.md",max_output_tokens:2600}),
