tools.exec_command({cmd:"rg -n 'revalid|archive|feedback|subject|graph|JSON|review' regulatory-change-impact-brief/references/contracts.md references/contracts.md",max_output_tokens:4500})
]);for(let i=0;i<results.length;i++)text({i,result:results[i]});

const results=await Promise.allSettled([
tools.exec_command({cmd:"PYTHONDONTWRITEBYTECODE=1 python3 -m unittest discover -s tests/contracts -p 'test_u02.py' -q",max_output_tokens:2500}),
tools.exec_command({cmd:"PYTHONDONTWRITEBYTECODE=1 python3 docs/verification/check-u01.py",max_output_tokens:3000}),
tools.exec_command({cmd:"sed -n '1,32p' tests/contracts/test_u02.py\nsed -n '162,275p' tests/contracts/test_u02.py\nsed -n '387,405p' TECHNICAL-DESIGN-AND-IMPLEMENTATION-PLAN.md",max_output_tokens:5600})
