import importlib.util,json,ast,re
from pathlib import Path
from copy import deepcopy
from jsonschema import Draft202012Validator
spec=importlib.util.spec_from_file_location('review_cases',Path('tests/contracts/test_u02.py'))
m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
case=m.SnapshotContracts();case.setUp()
try:
    s=deepcopy(m.CHAIN[5]);f=case.current_feedback(s)
    s['state']['feedback']=[f];s['produced_record_ids'].append(f['id'])
    approval=s['state']['approval_requirements'][0];approval.update(status='approved',feedback_ids=[f['id']])
    s['state']['proposed_actions'][0]['approval_status']='approved'
    # Overlapping approval requirements must remain unambiguous regardless of
    # subject grouping or generated record identity.
    other=deepcopy(approval);other['id']=m.new_record_id(s['run_id'],6,'approval')
    other['subject_ids'].append(m.CHAIN[4]['state']['impacts'][0]['id'])
    s['consumed_record_ids'].append(m.CHAIN[4]['state']['impacts'][0]['id'])
    s['state']['review_requests'][0]['subject_ids'].append(m.CHAIN[4]['state']['impacts'][0]['id'])
    s['state']['approval_requirements'].append(other);s['produced_record_ids'].append(other['id'])
    try:m.validate_snapshot(s,root=case.root,upstream=m.CHAIN[:5])
    except m.ContractError as e:print('OVERLAPPING GROUPED APPROVAL: rejected:',str(e))
    else:raise AssertionError('overlapping approval accepted')
    for replacement in (0,0.0):
        upstream=deepcopy(m.CHAIN[:4]);upstream[3]['state']['system_facts'][0]['value']=replacement
        try:m.validate_snapshot(deepcopy(m.CHAIN[4]),root=case.root,upstream=upstream)
        except m.ContractError as e:print('TYPED UPSTREAM',repr(replacement),'rejected:',str(e))
        else:raise AssertionError('typed substitution accepted')
finally:case.doCleanups()
paths=[Path('docs/verification/u02.md'),Path('docs/verification/u02-requirement-evidence.csv')]
for root in ('regulatory-change-impact-brief','tests'):
    paths.extend(p for p in Path(root).rglob('*') if p.is_file())
for p in paths:
    assert '__pycache__' not in p.parts,p
    value=p.read_text();assert all(line==line.rstrip() for line in value.splitlines()),p
    if p.suffix=='.py':ast.parse(value)
    if p.suffix=='.json':json.loads(value)
    if p.suffix=='.md':
        for target in re.findall(r'\]\(([^)]+)\)',value):
            if target.startswith(('http:','https:','#')):continue
            assert (p.parent/target.split('#')[0]).exists(),(p,target)
Draft202012Validator.check_schema(json.loads(Path('regulatory-change-impact-brief/references/schemas/contracts.schema.json').read_text()))
print('S PASS:',len(paths),'files; syntax, local Markdown links, whitespace, meta-schema and bytecode cleanliness')
